import AppKit
import AVFoundation
import UniformTypeIdentifiers

enum SongExport {
    static let sampleRate=48000.0
    static func frameCount(_ p:Project)->Int64{let steps=(p.song ?? [p.selected]).reduce(0){$0+(p.patterns[$1]?.length ?? 64)};let bpm10=max(400,Int((p.bpm*10).rounded()));return Int64(ceil(Double(steps)*sampleRate*150/Double(bpm10)))}
    static func render(_ project:Project,to url:URL)throws{
        tm_init(sampleRate);let t=Tracker(frame:NSRect(x:0,y:0,width:1440,height:900));guard t.valid(project) else{throw NSError(domain:"Termin Tracker",code:1,userInfo:[NSLocalizedDescriptionKey:"Invalid project snapshot"])};t.project=project;t.sync();tm_song_play(1);tm_start_step(0);tm_play(1)
        let format=AVAudioFormat(standardFormatWithSampleRate:sampleRate,channels:2)!,buffer=AVAudioPCMBuffer(pcmFormat:format,frameCapacity:4096)!
        let settings:[String:Any]=[AVFormatIDKey:kAudioFormatLinearPCM,AVSampleRateKey:sampleRate,AVNumberOfChannelsKey:2,AVLinearPCMBitDepthKey:24,AVLinearPCMIsFloatKey:false,AVLinearPCMIsBigEndianKey:false,AVLinearPCMIsNonInterleaved:false]
        let file=try AVAudioFile(forWriting:url,settings:settings,commonFormat:.pcmFormatFloat32,interleaved:false);let frames=frameCount(project);var done:Int64=0
        func block(_ count:Int,fade:Double=0)throws{buffer.frameLength=AVAudioFrameCount(count);let l=buffer.floatChannelData![0],r=buffer.floatChannelData![1];tm_render(l,r,Int32(count));if fade>0{for i in 0..<count{let g=Float(max(0,min(1,(fade-Double(i))/2400)));l[i]*=g;r[i]*=g}};try file.write(from:buffer)}
        while done<frames{let n=Int(min(4096,frames-done));try block(n);done+=Int64(n)}
        let f=project.fxSettings ?? FXSettings();let tail=Int64((f.tailSeconds(bpm:project.bpm)+1)*sampleRate);tm_export_tail(1);tm_play(0);done=0
        while done<tail{let n=Int(min(4096,tail-done));let remaining=tail-done;try block(n,fade:remaining<6500 ? Double(remaining):0);done+=Int64(n)}
        tm_export_tail(0)
    }
    static func worker(_ args:[String])->Int32{guard args.count==4 else{return 2};do{let project=try JSONDecoder().decode(Project.self,from:Data(contentsOf:URL(fileURLWithPath:args[2])));try render(project,to:URL(fileURLWithPath:args[3]));return 0}catch{FileHandle.standardError.write(Data(error.localizedDescription.utf8));return 1}}
    static func selfTest()throws{var p=Project();p.bpm=120;p.song=[0,1,0];var a=Pattern(),b=Pattern();a.length=4;b.length=4;a.cells[0][0]=Cell(notes:[60],instrument:3,velocity:100,volume:100,pan:-50);b.cells[0][0]=Cell(notes:[67],instrument:3,velocity:100,volume:100,pan:50);p.patterns=[0:a,1:b];var f=FXSettings.preset(1);f.feedback=0;p.fxSettings=f;let data=try JSONEncoder().encode(p);let copy=try JSONDecoder().decode(Project.self,from:data);precondition(copy.fxSettings==f&&frameCount(copy)==72000);let url=FileManager.default.temporaryDirectory.appendingPathComponent("TrackerMacExportTest-\(UUID().uuidString).wav");defer{try? FileManager.default.removeItem(at:url)};try render(copy,to:url);let file=try AVAudioFile(forReading:url,commonFormat:.pcmFormatFloat32,interleaved:false);precondition(file.fileFormat.sampleRate==48000&&file.fileFormat.channelCount==2&&file.fileFormat.streamDescription.pointee.mBitsPerChannel==24);let buf=AVAudioPCMBuffer(pcmFormat:file.processingFormat,frameCapacity:AVAudioFrameCount(file.length))!;try file.read(into:buf);precondition(file.length>72000);let l=buf.floatChannelData![0],r=buf.floatChannelData![1];for i in 0..<3{let start=i*24000;var le:Float=0,re:Float=0;for j in start..<start+5000{le+=l[j]*l[j];re+=r[j]*r[j]};if i==1{precondition(re>le*10&&re>0.01)}else{precondition(le>re*10&&le>0.01)}};print("Song chain A-B-A, stereo 24-bit WAV, mix and FX settings roundtrip passed")}
}

extension Tracker {
    func exportAudio(patternOnly:Bool=false){guard exportProcess==nil else{message="Export already running";return};flushMIDIChord();var snapshot=project;if patternOnly{snapshot.song=[project.selected]};let panel=NSSavePanel();panel.allowedContentTypes=[.wav];panel.nameFieldStringValue=(projectURL?.deletingPathExtension().lastPathComponent ?? "Termin Tracker")+(patternOnly ? "-P\(project.selected)":"-Song")+".wav";panel.title="Export stereo audio (48 kHz / 24-bit WAV)";guard panel.runModal() == .OK,let target=panel.url else{return};let fm=FileManager.default,temp=fm.temporaryDirectory.appendingPathComponent("TrackerMac-\(UUID().uuidString).json"),partial=target.deletingLastPathComponent().appendingPathComponent(".TrackerMac-\(UUID().uuidString).wav");do{try JSONEncoder().encode(snapshot).write(to:temp,options:.atomic);let proc=Process();proc.executableURL=Bundle.main.executableURL ?? URL(fileURLWithPath:CommandLine.arguments[0]);proc.arguments=["--render-song",temp.path,partial.path];let errors=Pipe();proc.standardError=errors;proc.standardOutput=FileHandle.nullDevice;exportProcess=proc;message="Exporting WAV…  (Esc cancel)";needsDisplay=true;proc.terminationHandler={[weak self] p in let err=String(data:errors.fileHandleForReading.readDataToEndOfFile(),encoding:.utf8) ?? "";DispatchQueue.main.async{defer{try? fm.removeItem(at:temp);try? fm.removeItem(at:partial);self?.exportProcess=nil;self?.needsDisplay=true};guard p.terminationStatus==0 else{self?.message=p.terminationReason == .uncaughtSignal ? "Export cancelled":"Export failed: \(err)";return};do{if fm.fileExists(atPath:target.path){_ = try fm.replaceItemAt(target,withItemAt:partial)}else{try fm.moveItem(at:partial,to:target)};self?.message="Exported: \(target.lastPathComponent)"}catch{self?.message="Export failed: \(error.localizedDescription)"}}};try proc.run()}catch{exportProcess=nil;try? fm.removeItem(at:temp);try? fm.removeItem(at:partial);message="Export failed: \(error.localizedDescription)"};held.removeAll()}
    func cancelExport(){if let p=exportProcess,p.isRunning{p.terminate();message="Cancelling export…"}}
}
